{"path": "book_store.py", "content": "from collections import Counter
from functools import lru_cache

BOOK_PRICE = 800  # cents
DISCOUNTS = {1: 0, 2: 5, 3: 10, 4: 20, 5: 25}
GROUP_PRICE = {
    size: size * BOOK_PRICE * (100 - pct) // 100 for size, pct in DISCOUNTS.items()
}


def total(basket):
    """Return the cheapest price of the basket, in cents."""
    counts = tuple(sorted(Counter(basket).values(), reverse=True))
    return _best(counts)


@lru_cache(maxsize=None)
def _best(counts):
    counts = tuple(c for c in counts if c > 0)
    if not counts:
        return 0
    best = None
    # Taking one copy from each of the k most plentiful titles is optimal
    # for a group of size k, so only group sizes need to be tried.
    for size in range(1, len(counts) + 1):
        rest = [c - 1 if i < size else c for i, c in enumerate(counts)]
        cost = GROUP_PRICE[size] + _best(tuple(sorted(rest, reverse=True)))
        if best is None or cost < best:
            best = cost
    return best
